-- Additive extension: preserve all original tables, attempts, answers, grades and snapshots.
alter table public.assignments add column type text not null default 'assignment' check(type in ('assignment','exam'));
alter table public.assignments add column archived boolean not null default false;
alter table public.assignments add column published_version int not null default 0;
create table public.assessment_versions(id uuid primary key default gen_random_uuid(),assessment_id uuid not null references public.assignments,version int not null check(version>0),document jsonb not null,created_at timestamptz not null default now(),unique(assessment_id,version));
create table public.assessment_drafts(id uuid primary key default gen_random_uuid(),assessment_id uuid not null unique references public.assignments,document jsonb not null,updated_at timestamptz not null default now());
create table private.assessment_keys(assessment_id uuid not null,version int not null,keys jsonb not null default '{}',primary key(assessment_id,version),foreign key(assessment_id,version) references public.assessment_versions(assessment_id,version));
create table private.verified_checkpoints(attempt_id uuid primary key references public.attempts on delete cascade,revision int not null,payload jsonb not null,outcomes jsonb not null,objective_grades jsonb not null,practical_score numeric not null,objective_score numeric not null,accepted_at timestamptz not null default now(),idempotency_key uuid);
alter table public.attempts add column deadline_at timestamptz;
alter table public.attempts add column checkpoint_revision int not null default 0;
alter table public.attempts add column auto_submitted boolean not null default false;
alter table public.attempts drop constraint attempts_status_check;
alter table public.attempts add constraint attempts_status_check check(status in ('in_progress','submitted','pending_review','graded','expired'));
alter table public.grading_results drop constraint grading_results_question_id_fkey;
alter table public.grading_results add column automatic boolean not null default false;
alter table public.grading_summaries drop constraint grading_summaries_practical_score_check;
alter table public.grading_summaries drop constraint grading_summaries_theory_score_check;
alter table public.grading_summaries add constraint practical_score_bounded check(practical_score between 0 and 10000);
alter table public.grading_summaries add constraint theory_score_bounded check(theory_score between 0 and 10000);
alter table public.task_results drop constraint task_results_points_check;
alter table public.task_results add constraint task_points_bounded check(points between 0 and 1000);
alter table public.assessment_versions enable row level security;
alter table public.assessment_drafts enable row level security;
alter table private.assessment_keys enable row level security;
alter table private.verified_checkpoints enable row level security;
revoke all on public.assessment_versions,public.assessment_drafts from anon,authenticated;
grant select on public.assessment_versions,public.assessment_drafts to authenticated;
create policy version_read on public.assessment_versions for select to authenticated using((select public.is_instructor()) or exists(select 1 from public.assignments a where a.id=assessment_id and a.visible and not a.archived) or exists(select 1 from public.attempts a where a.assignment_id=assessment_id and a.assignment_version=version and a.student_id=(select auth.uid())));
create policy draft_instructor on public.assessment_drafts for select to authenticated using((select public.is_instructor()));
create index exam_expiry on public.attempts(deadline_at) where status='in_progress';
create index versions_assessment on public.assessment_versions(assessment_id,version);

create function public.save_assessment(p_id uuid,p_document jsonb,p_publish boolean default false) returns uuid language plpgsql security definer set search_path='' as $$
declare target uuid:=coalesce(p_id,gen_random_uuid());doc jsonb:=p_document;q jsonb;t jsonb;r jsonb;s jsonb;public_questions jsonb:='[]';answer_keys jsonb:='{}';next_version int;seen text[]:='{}';qid text;total numeric:=0;
begin
 if jsonb_typeof(doc) is distinct from 'object' or not (doc ?& array['schemaVersion','title','type','format','projectName','durationMinutes','attemptLimit','sections','questions','starter','releaseImmediately','reviewAnswers','gateTheory','requireComplete']) then raise exception 'Assessment definition fields are required';end if;
 if auth.uid() is null or not public.is_instructor() then raise exception 'Instructor authorization required'; end if;
 if octet_length(doc::text)>1000000 or doc->>'schemaVersion'<>'1' or length(trim(doc->>'title')) not between 1 and 180 or doc->>'type' not in ('assignment','exam') or doc->>'format' not in ('practical','theory','mixed') or doc->>'projectName' !~ '^[a-zA-Z0-9_-]{1,60}$' or (doc->>'attemptLimit')::int not between 1 and 20 or (doc->>'durationMinutes')::int not between 0 and 1440 or (doc->>'type'='exam' and (doc->>'durationMinutes')::int<1) then raise exception 'Invalid assessment configuration'; end if;
 if jsonb_typeof(doc->'questions')<>'array' or jsonb_array_length(doc->'questions')>100 or jsonb_typeof(doc->'sections')<>'array' or jsonb_array_length(doc->'sections')>20 then raise exception 'Invalid assessment content'; end if;
 if nullif(doc->>'startsAt','')::timestamptz>=nullif(doc->>'endsAt','')::timestamptz then raise exception 'Availability ends before start'; end if;
 for q in select value from jsonb_array_elements(doc->'questions') loop
  qid:=q->>'id';if qid is null or qid !~ '^[a-zA-Z0-9_-]{1,80}$' or qid=any(seen) or q->>'kind' not in ('single','multiple','boolean','short','long','scenario','interpretation') or length(trim(q->>'prompt')) not between 1 and 8000 or (q->>'points')::numeric not between 0 and 1000 then raise exception 'Invalid question'; end if;seen:=array_append(seen,qid);
  if not (q->>'manual')::boolean and q->>'kind' in ('single','multiple','boolean') then
   if jsonb_typeof(q->'correctAnswers')<>'array' or jsonb_array_length(q->'correctAnswers')<1 or (q->>'kind'<>'multiple' and jsonb_array_length(q->'correctAnswers')<>1) or not ((q->'options') @> (q->'correctAnswers')) then raise exception 'Objective questions require a valid private answer key'; end if;
  end if;
  answer_keys:=answer_keys||jsonb_build_object(qid,jsonb_build_object('correctAnswers',coalesce(q->'correctAnswers','[]'),'explanation',coalesce(q->>'explanation','')));
  public_questions:=public_questions||jsonb_build_array(q-'correctAnswers'-'explanation');total:=total+(q->>'points')::numeric;
 end loop;
 seen:='{}';
 for s in select value from jsonb_array_elements(doc->'sections') loop
  if jsonb_typeof(s->'tasks')<>'array' or jsonb_array_length(s->'tasks')>30 then raise exception 'Invalid task section'; end if;
  for t in select value from jsonb_array_elements(s->'tasks') loop
   if t->>'id'=any(seen) or t->>'id' !~ '^[a-zA-Z0-9_-]{1,80}$' or (t->>'points')::numeric not between 0 and 1000 or jsonb_typeof(t->'rules')<>'array' or jsonb_array_length(t->'rules') not between 1 and 20 then raise exception 'Invalid task'; end if;seen:=array_append(seen,t->>'id');total:=total+(t->>'points')::numeric;
   for r in select value from jsonb_array_elements(t->'rules') loop if r->>'type' not in ('repository','file','branch','commits','message','merged','isolation','legacy') then raise exception 'Unsupported validation rule'; end if;end loop;
  end loop;
 end loop;
 if total>10000 or (p_publish and total<=0) then raise exception 'Invalid total points'; end if;
 insert into public.assignments(id,title,description,type,visible) values(target,doc->>'title',coalesce(doc->>'description',''),doc->>'type',false) on conflict(id) do nothing;
 -- Serialize publishers before allocating a version number.
 perform 1 from public.assignments where id=target for update;
 insert into public.assessment_drafts(assessment_id,document) values(target,doc) on conflict(assessment_id) do update set document=excluded.document,updated_at=now();
 if p_publish then
  select coalesce(max(version),0)+1 into next_version from public.assessment_versions where assessment_id=target;
  insert into public.assessment_versions(assessment_id,version,document) values(target,next_version,jsonb_set(doc,'{questions}',public_questions));
  insert into private.assessment_keys values(target,next_version,answer_keys);
  update public.assignments set version=next_version,published_version=next_version,title=doc->>'title',description=doc->>'description',type=doc->>'type',visible=true,archived=false,starts_at=nullif(doc->>'startsAt','')::timestamptz,deadline=nullif(doc->>'deadline','')::timestamptz,review_answers=coalesce((doc->>'reviewAnswers')::boolean,true) where id=target;
 end if;
 insert into public.audit_logs(actor_id,action,target_id) values(auth.uid(),case when p_publish then 'assessment.published' else 'assessment.draft_saved' end,target::text);return target;
end $$;
create function public.set_assessment_visibility(p_id uuid,p_visible boolean,p_archive boolean default false) returns void language plpgsql security definer set search_path='' as $$begin
 if auth.uid() is null or not public.is_instructor() then raise exception 'Instructor authorization required'; end if;
 if p_visible and not exists(select 1 from public.assessment_versions v join public.assignments a on a.id=v.assessment_id and a.published_version=v.version where a.id=p_id) then raise exception 'Publish a version before making it visible'; end if;
 update public.assignments set visible=p_visible and not p_archive,archived=p_archive where id=p_id;insert into public.audit_logs(actor_id,action,target_id) values(auth.uid(),'assessment.visibility',p_id::text);end $$;
create function public.duplicate_assessment(p_id uuid) returns uuid language plpgsql security definer set search_path='' as $$declare doc jsonb;begin
 if auth.uid() is null or not public.is_instructor() then raise exception 'Instructor authorization required'; end if;
 select document into doc from public.assessment_drafts where assessment_id=p_id;if doc is null then raise exception 'Draft not found';end if;return public.save_assessment(null,jsonb_set(doc,'{title}',to_jsonb((doc->>'title')||' (copy)')),false);end $$;

create function private.finish_assessment(p_attempt uuid,p_auto boolean,p_key uuid default null) returns uuid language plpgsql security definer set search_path='' as $$
declare a public.attempts;c private.verified_checkpoints;doc jsonb;item jsonb;q jsonb;ref uuid;manual_pending boolean;auto_score numeric:=0;
begin
 select * into a from public.attempts where id=p_attempt for update;if a.id is null then raise exception 'Attempt not found';end if;if a.status<>'in_progress' then return a.receipt;end if;
 select document into doc from public.assessment_versions where assessment_id=a.assignment_id and version=a.assignment_version;
 select * into c from private.verified_checkpoints where attempt_id=a.id;
 if c.attempt_id is null then c.payload:='{"snapshot":{"version":1,"entries":{"/":{"kind":"dir","data":[]}}},"answers":{},"events":[]}';c.outcomes:='[]';c.objective_grades:='[]';c.practical_score:=0;c.objective_score:=0;end if;
 manual_pending:=exists(select 1 from jsonb_array_elements(doc->'questions') x where ((x->>'manual')::boolean or x->>'kind' not in ('single','multiple','boolean')) and (x->>'points')::numeric>0);
 ref:=gen_random_uuid();
 insert into public.workspace_snapshots(attempt_id,snapshot) values(a.id,c.payload->'snapshot');
 insert into public.student_answers(attempt_id,question_id,answer) select a.id,key,value from jsonb_each_text(coalesce(c.payload->'answers','{}'));
 for item in select value from jsonb_array_elements(c.outcomes) loop insert into public.task_results(attempt_id,task_key,passed,points) values(a.id,item->>'id',(item->>'passed')::boolean,case when (item->>'passed')::boolean then (item->>'points')::numeric else 0 end);end loop;
 for item in select value from jsonb_array_elements(c.objective_grades) loop insert into public.grading_results(attempt_id,question_id,points,grader_id,automatic) values(a.id,item->>'question_id',(item->>'points')::numeric,a.student_id,true);end loop;
 for item in select value from jsonb_array_elements(coalesce(c.payload->'events','[]')) loop insert into public.command_events(attempt_id,sequence,event) values(a.id,(item->>'sequence')::int,item);end loop;
 insert into public.grading_summaries(attempt_id,practical_score,theory_score,released) values(a.id,c.practical_score,c.objective_score,not manual_pending and coalesce((doc->>'releaseImmediately')::boolean,false));
 update public.attempts set status=case when p_auto then 'expired' when manual_pending then 'pending_review' else 'submitted' end,auto_submitted=p_auto,receipt=ref,submitted_at=case when p_auto then deadline_at else clock_timestamp() end,idempotency_key=p_key where id=a.id;
 insert into public.audit_logs(actor_id,action,target_id) values(a.student_id,case when p_auto then 'exam.auto_submitted' else 'assessment.submitted' end,a.id::text);return ref;
end $$;
revoke all on function private.finish_assessment(uuid,boolean,uuid) from public,anon,authenticated;
create function public.expire_due_attempts() returns int language plpgsql security definer set search_path='' as $$declare a record;n int:=0;begin
 for a in select id from public.attempts where status='in_progress' and deadline_at<=clock_timestamp() for update skip locked loop perform private.finish_assessment(a.id,true);n:=n+1;end loop;return n;end $$;
revoke all on function public.expire_due_attempts() from public,anon,authenticated;grant execute on function public.expire_due_attempts() to service_role;

create function public.start_assessment(p_assessment uuid) returns jsonb language plpgsql security definer set search_path='' as $$
declare actor uuid:=auth.uid();a public.assignments;doc jsonb;last_attempt public.attempts;new_attempt public.attempts;allowed int;due timestamptz;started timestamptz:=clock_timestamp();limit_count int;
begin
 if actor is null or not exists(select 1 from auth.users where id=actor and email_confirmed_at is not null) or not exists(select 1 from public.profiles where id=actor) then raise exception 'Verified account and academic profile required';end if;
 select * into a from public.assignments where id=p_assessment for share;select document into doc from public.assessment_versions where assessment_id=a.id and version=a.published_version;
 if a.id is null or not a.visible or a.archived or doc is null then raise exception 'Assessment is not published';end if;
 insert into public.student_enrollments(student_id,assignment_id) values(actor,a.id) on conflict do nothing;
 select retakes_remaining into allowed from public.student_enrollments where student_id=actor and assignment_id=a.id for update;
 select * into last_attempt from public.attempts where student_id=actor and assignment_id=a.id order by attempt_number desc limit 1;
 if last_attempt.id is not null and last_attempt.status='in_progress' then
  if last_attempt.deadline_at is not null and last_attempt.deadline_at<=clock_timestamp() then perform private.finish_assessment(last_attempt.id,true);else return jsonb_build_object('id',last_attempt.id);end if;
 end if;
 if (nullif(doc->>'startsAt','')::timestamptz>started) or (nullif(doc->>'endsAt','')::timestamptz<=started) or (nullif(doc->>'deadline','')::timestamptz<=started) then raise exception 'Assessment is closed or not open yet';end if;
 select count(*) into limit_count from public.attempts where student_id=actor and assignment_id=a.id;
 if limit_count>=coalesce((doc->>'attemptLimit')::int,1) and allowed<=0 then raise exception 'Attempt limit reached';end if;
 if limit_count>=coalesce((doc->>'attemptLimit')::int,1) and allowed>0 then update public.student_enrollments set retakes_remaining=retakes_remaining-1 where student_id=actor and assignment_id=a.id;end if;
 due:=least(nullif(doc->>'endsAt','')::timestamptz,nullif(doc->>'deadline','')::timestamptz,case when a.type='exam' then started+make_interval(mins=>(doc->>'durationMinutes')::int) else null end);
 insert into public.attempts(student_id,assignment_id,assignment_version,attempt_number,created_at,deadline_at) values(actor,a.id,a.published_version,coalesce(last_attempt.attempt_number,0)+1,started,due) returning * into new_attempt;return jsonb_build_object('id',new_attempt.id);
end $$;
create function public.assessment_state(p_attempt uuid) returns jsonb language plpgsql security definer set search_path='' as $$declare a public.attempts;doc jsonb;c private.verified_checkpoints;begin
 select * into a from public.attempts where id=p_attempt for update;if a.id is null or auth.uid() is null or (a.student_id<>auth.uid() and not public.is_instructor()) then raise exception 'Attempt not authorized';end if;
 if a.status='in_progress' and a.deadline_at is not null and a.deadline_at<=clock_timestamp() then perform private.finish_assessment(a.id,true);select * into a from public.attempts where id=p_attempt;end if;
 select document into doc from public.assessment_versions where assessment_id=a.assignment_id and version=a.assignment_version;select * into c from private.verified_checkpoints where attempt_id=a.id;
 if c.attempt_id is null and a.status<>'in_progress' then c.payload:=jsonb_build_object('snapshot',(select snapshot from public.workspace_snapshots where attempt_id=a.id),'answers',coalesce((select jsonb_object_agg(question_id,answer) from public.student_answers where attempt_id=a.id),'{}'),'events',coalesce((select jsonb_agg(event order by sequence) from public.command_events where attempt_id=a.id),'[]'),'cwd','/','config','{}'::jsonb);end if;
 return to_jsonb(a)||jsonb_build_object('server_now',clock_timestamp(),'definition',doc,'payload',case when a.status='in_progress' or public.is_instructor() or coalesce((doc->>'reviewAnswers')::boolean,true) then c.payload else null end);
end $$;
create function public.accept_assessment_checkpoint(p_student uuid,p_attempt uuid,p_revision int,p_payload jsonb,p_outcomes jsonb,p_grades jsonb,p_practical numeric,p_objective numeric,p_finalize boolean,p_key uuid) returns jsonb language plpgsql security definer set search_path='' as $$
declare a public.attempts;ref uuid;doc jsonb;total_points numeric:=0;begin
 select * into a from public.attempts where id=p_attempt for update;if a.id is null or a.student_id<>p_student then raise exception 'Attempt ownership mismatch';end if;
 if a.status<>'in_progress' then if p_finalize and (a.idempotency_key=p_key or a.auto_submitted) then return jsonb_build_object('receipt',a.receipt,'revision',a.checkpoint_revision,'status',a.status);end if;raise exception 'Attempt is finalized';end if;
 if a.deadline_at is not null and a.deadline_at<=clock_timestamp() then perform private.finish_assessment(a.id,true);select * into a from public.attempts where id=p_attempt;return jsonb_build_object('receipt',a.receipt,'revision',a.checkpoint_revision,'status',a.status,'expired',true);end if;
 if exists(select 1 from private.verified_checkpoints where attempt_id=a.id and idempotency_key=p_key) then return jsonb_build_object('revision',a.checkpoint_revision,'status','in_progress');end if;
 if a.checkpoint_revision<>p_revision then raise exception 'Checkpoint conflict: another tab has saved newer work';end if;
 if octet_length(p_payload::text)>9000000 or p_practical<0 or p_objective<0 or p_practical+p_objective>10000 then raise exception 'Invalid verified checkpoint';end if;
 select document into doc from public.assessment_versions where assessment_id=a.assignment_id and version=a.assignment_version;
 if p_finalize and coalesce((doc->>'requireComplete')::boolean,false) then
  if exists(select 1 from jsonb_array_elements(p_outcomes) x where not coalesce((x->>'bonus')::boolean,false) and not (x->>'passed')::boolean) or exists(select 1 from jsonb_array_elements(doc->'questions') x where (x->>'required')::boolean and length(trim(coalesce(p_payload->'answers'->>(x->>'id'),'')))=0) then raise exception 'Required work is incomplete';end if;
 end if;
 insert into private.verified_checkpoints values(a.id,p_revision+1,p_payload,p_outcomes,p_grades,p_practical,p_objective,clock_timestamp(),p_key) on conflict(attempt_id) do update set revision=excluded.revision,payload=excluded.payload,outcomes=excluded.outcomes,objective_grades=excluded.objective_grades,practical_score=excluded.practical_score,objective_score=excluded.objective_score,accepted_at=excluded.accepted_at,idempotency_key=excluded.idempotency_key;
 update public.attempts set checkpoint_revision=checkpoint_revision+1 where id=a.id;
 if p_finalize then ref:=private.finish_assessment(a.id,false,p_key);end if;
 return jsonb_build_object('receipt',ref,'revision',p_revision+1,'status',case when p_finalize then 'submitted' else 'in_progress' end,'server_now',clock_timestamp());
end $$;
revoke all on function public.accept_assessment_checkpoint(uuid,uuid,int,jsonb,jsonb,jsonb,numeric,numeric,boolean,uuid) from public,anon,authenticated;grant execute on function public.accept_assessment_checkpoint(uuid,uuid,int,jsonb,jsonb,jsonb,numeric,numeric,boolean,uuid) to service_role;

create function public.grade_assessment(p_attempt uuid,p_grades jsonb,p_feedback text,p_release boolean) returns void language plpgsql security definer set search_path='' as $$
declare a public.attempts;doc jsonb;item jsonb;q jsonb;seen text[]:='{}';total numeric;manual_count int;begin
 if auth.uid() is null or not public.is_instructor() then raise exception 'Instructor authorization required';end if;
 select * into a from public.attempts where id=p_attempt for update;if a.id is null or a.status='in_progress' then raise exception 'Finalized attempt required';end if;
 select document into doc from public.assessment_versions where assessment_id=a.assignment_id and version=a.assignment_version;
 if length(p_feedback)>5000 or jsonb_typeof(p_grades)<>'array' then raise exception 'Invalid grading payload';end if;
 select count(*) into manual_count from jsonb_array_elements(doc->'questions') x where ((x->>'manual')::boolean or x->>'kind' not in ('single','multiple','boolean')) and (x->>'points')::numeric>0;
 if jsonb_array_length(p_grades)<>manual_count then raise exception 'Grade every manual question';end if;
 for item in select value from jsonb_array_elements(p_grades) loop
  select value into q from jsonb_array_elements(doc->'questions') where value->>'id'=item->>'question_id';
  if q is null or item->>'question_id'=any(seen) or (not (q->>'manual')::boolean and q->>'kind' in ('single','multiple','boolean')) or (item->>'points') is null or (item->>'points')::numeric not between 0 and (q->>'points')::numeric then raise exception 'Invalid manual grade';end if;
  seen:=array_append(seen,item->>'question_id');insert into public.grading_results(attempt_id,question_id,points,grader_id,automatic) values(a.id,item->>'question_id',(item->>'points')::numeric,auth.uid(),false) on conflict(attempt_id,question_id) do update set points=excluded.points,grader_id=excluded.grader_id,automatic=false,updated_at=now();
 end loop;
 select coalesce(sum(points),0) into total from public.grading_results where attempt_id=a.id;
 update public.grading_summaries set theory_score=total,feedback=p_feedback,released=p_release where attempt_id=a.id;update public.attempts set status='graded' where id=a.id;
 insert into public.audit_logs(actor_id,action,target_id) values(auth.uid(),case when p_release then 'grade.published' else 'grade.saved' end,a.id::text);
end $$;

-- Old unverified draft RPC cannot update timed attempts. New autosaves use the Edge verifier.
create or replace function public.save_checkpoint(p_attempt uuid,p_payload jsonb) returns void language plpgsql security definer set search_path='' as $$declare a public.attempts;begin
 select * into a from public.attempts where id=p_attempt for update;if auth.uid() is null or a.student_id<>auth.uid() or a.id is null or a.status<>'in_progress' or a.deadline_at is not null then raise exception 'Use verified assessment autosave for this attempt';end if;
 if octet_length(p_payload::text)>9000000 or p_payload->>'version'<>'1' then raise exception 'Invalid checkpoint';end if;
 insert into public.workspace_drafts(attempt_id,payload) values(p_attempt,p_payload) on conflict(attempt_id) do update set payload=excluded.payload,updated_at=now();end $$;
revoke all on function public.save_assessment(uuid,jsonb,boolean),public.set_assessment_visibility(uuid,boolean,boolean),public.duplicate_assessment(uuid),public.start_assessment(uuid),public.assessment_state(uuid),public.grade_assessment(uuid,jsonb,text,boolean) from public,anon;
grant execute on function public.save_assessment(uuid,jsonb,boolean),public.set_assessment_visibility(uuid,boolean,boolean),public.duplicate_assessment(uuid),public.start_assessment(uuid),public.assessment_state(uuid),public.grade_assessment(uuid,jsonb,text,boolean) to authenticated;

drop policy snapshot_read on public.workspace_snapshots;
create policy snapshot_read on public.workspace_snapshots for select to authenticated using((select public.is_instructor()) or exists(select 1 from public.attempts a join public.assessment_versions v on v.assessment_id=a.assignment_id and v.version=a.assignment_version where a.id=attempt_id and a.student_id=(select auth.uid()) and coalesce((v.document->>'reviewAnswers')::boolean,true)));
drop policy answers_read on public.student_answers;
create policy answers_read on public.student_answers for select to authenticated using((select public.is_instructor()) or exists(select 1 from public.attempts a join public.assessment_versions v on v.assessment_id=a.assignment_id and v.version=a.assignment_version where a.id=attempt_id and a.student_id=(select auth.uid()) and coalesce((v.document->>'reviewAnswers')::boolean,true)));

create function public.assessment_verification_context(p_attempt uuid,p_student uuid) returns jsonb language plpgsql security definer set search_path='' as $$declare a public.attempts;d jsonb;k jsonb;p jsonb;begin
 select * into a from public.attempts where id=p_attempt and student_id=p_student;if a.id is null then raise exception 'Attempt not authorized';end if;
 select document into d from public.assessment_versions where assessment_id=a.assignment_id and version=a.assignment_version;select keys into k from private.assessment_keys where assessment_id=a.assignment_id and version=a.assignment_version;select jsonb_build_object('full_name',full_name,'department',department) into p from public.profiles where id=p_student;
 return jsonb_build_object('attempt',to_jsonb(a),'definition',d,'keys',coalesce(k,'{}'),'identity',p);end $$;
revoke all on function public.assessment_verification_context(uuid,uuid) from public,anon,authenticated;grant execute on function public.assessment_verification_context(uuid,uuid) to service_role;
create function private.immutable_assessment_version() returns trigger language plpgsql set search_path='' as $$begin raise exception 'Published assessment versions are immutable; publish a new version';end $$;
create trigger immutable_version before update or delete on public.assessment_versions for each row execute function private.immutable_assessment_version();

insert into public.assignments(id,title,description,visible) values('b6f4b6d0-5fe2-4e4d-b9a5-000000000001','Git Fundamentals, Commits, Branching & Merging','Build a local repository, tell the story of your changes, and bring two branches together.',true) on conflict(id) do nothing;
insert into public.assessment_versions(assessment_id,version,document) select a.id,v.version,'{"schemaVersion":1,"title":"Git Fundamentals, Commits, Branching & Merging","description":"Build a local repository, tell the story of your changes, and bring two branches together.","instructions":"Complete the local Git tasks using plain text files. Then answer the theory questions and reflections.","type":"assignment","format":"mixed","projectName":"IEEE-Git-Task","durationMinutes":0,"attemptLimit":1,"startsAt":null,"endsAt":null,"deadline":null,"releaseImmediately":false,"reviewAnswers":true,"gateTheory":true,"requireComplete":true,"starter":{"files":{},"initialize":false,"commit":false},"sections":[{"id":"init","title":"Repository initialization","description":"Set up your project and make it your own.","steps":["Verify Git availability and configure your name and email.","Create and enter IEEE-Git-Task. Initialize a repository with main as its primary branch.","Create about.txt, goals.txt and notes.txt with the contents below.","Inspect status and list hidden files to find .git."],"tasks":[{"id":"repo","title":"Local repository on main with configured identity","instructions":"Verify Git availability and configure your name and email.\nCreate and enter IEEE-Git-Task. Initialize a repository with main as its primary branch.\nCreate about.txt, goals.txt and notes.txt with the contents below.\nInspect status and list hidden files to find .git.","points":5,"bonus":false,"rules":[{"type":"legacy","outcomeId":"repo"}]},{"id":"files","title":"Required project files contain your information and course content","instructions":"Verify Git availability and configure your name and email.\nCreate and enter IEEE-Git-Task. Initialize a repository with main as its primary branch.\nCreate about.txt, goals.txt and notes.txt with the contents below.\nInspect status and list hidden files to find .git.","points":10,"bonus":false,"rules":[{"type":"legacy","outcomeId":"files"}]}]},{"id":"commits","title":"Staging & commits","description":"Small commits. A clear story.","steps":["Stage only about.txt, inspect status, and commit with “Add personal information”.","Introduce goals.txt and notes.txt in separate commits with meaningful messages.","Add two more goals and commit the updated goals.","Inspect your short commit history. You should have at least four commits."],"tasks":[{"id":"separate","title":"The first three files were introduced in separate focused commits","instructions":"Stage only about.txt, inspect status, and commit with “Add personal information”.\nIntroduce goals.txt and notes.txt in separate commits with meaningful messages.\nAdd two more goals and commit the updated goals.\nInspect your short commit history. You should have at least four commits.","points":10,"bonus":false,"rules":[{"type":"legacy","outcomeId":"separate"}]},{"id":"goals","title":"Two additional goals saved in a later meaningful commit","instructions":"Stage only about.txt, inspect status, and commit with “Add personal information”.\nIntroduce goals.txt and notes.txt in separate commits with meaningful messages.\nAdd two more goals and commit the updated goals.\nInspect your short commit history. You should have at least four commits.","points":10,"bonus":false,"rules":[{"type":"legacy","outcomeId":"goals"}]}]},{"id":"branches","title":"Branching & switching","description":"A safe space to try something new.","steps":["Create feature/skills and switch to it.","Create skills.txt containing Problem Solving, Communication and Teamwork. Commit the file.","Switch to main and observe the file is absent. Switch back and observe it returns.","Be ready to explain branch isolation."],"tasks":[{"id":"feature","title":"feature/skills contains the three committed skills","instructions":"Create feature/skills and switch to it.\nCreate skills.txt containing Problem Solving, Communication and Teamwork. Commit the file.\nSwitch to main and observe the file is absent. Switch back and observe it returns.\nBe ready to explain branch isolation.","points":10,"bonus":false,"rules":[{"type":"legacy","outcomeId":"feature"}]},{"id":"isolation","title":"History shows skills introduced after the branch point","instructions":"Create feature/skills and switch to it.\nCreate skills.txt containing Problem Solving, Communication and Teamwork. Commit the file.\nSwitch to main and observe the file is absent. Switch back and observe it returns.\nBe ready to explain branch isolation.","points":10,"bonus":false,"rules":[{"type":"legacy","outcomeId":"isolation"}]}]},{"id":"merge","title":"Bring it all together","description":"Two lines of work, one shared history.","steps":["Ensure feature changes are committed. Switch to main and merge feature/skills.","Verify skills.txt is on main and inspect history.","Explain which branch received changes, the merge type, and whether a new commit was created."],"tasks":[{"id":"merged","title":"Feature history and skills are present on main","instructions":"Ensure feature changes are committed. Switch to main and merge feature/skills.\nVerify skills.txt is on main and inspect history.\nExplain which branch received changes, the merge type, and whether a new commit was created.","points":15,"bonus":false,"rules":[{"type":"legacy","outcomeId":"merged"}]},{"id":"clean","title":"Finish on main with a clean working tree","instructions":"Ensure feature changes are committed. Switch to main and merge feature/skills.\nVerify skills.txt is on main and inspect history.\nExplain which branch received changes, the merge type, and whether a new commit was created.","points":5,"bonus":false,"rules":[{"type":"legacy","outcomeId":"clean"}]}]},{"id":"bonus","title":"Different histories","description":"Optional · Explore a three-way merge.","steps":["From main, create feature/hobbies. Add hobbies.txt with three hobbies and commit.","Back on main, add “Assignment 1 completed.” to notes.txt and commit.","Merge feature/hobbies into main. Inspect the graph across all branches.","Explain the merge, how it differs from Part 4, why Git creates a merge commit, and what the graph reveals."],"tasks":[{"id":"bonus","title":"Diverged hobbies and completion histories joined by a merge commit","instructions":"From main, create feature/hobbies. Add hobbies.txt with three hobbies and commit.\nBack on main, add “Assignment 1 completed.” to notes.txt and commit.\nMerge feature/hobbies into main. Inspect the graph across all branches.\nExplain the merge, how it differs from Part 4, why Git creates a merge commit, and what the graph reveals.","points":10,"bonus":true,"rules":[{"type":"legacy","outcomeId":"bonus"}]}]}],"questions":[{"id":"q1","prompt":"What is the difference between Git and GitHub?","kind":"long","points":2,"options":[],"manual":true,"required":true},{"id":"q2","prompt":"What is a repository? What is stored inside the hidden .git directory?","kind":"long","points":2,"options":[],"manual":true,"required":true},{"id":"q3","prompt":"Explain the difference between the Working Directory, Staging Area, and Local Repository.","kind":"long","points":3,"options":[],"manual":true,"required":true},{"id":"q4","prompt":"What is the difference between git add and git commit?","kind":"long","points":2,"options":[],"manual":true,"required":true},{"id":"q5","prompt":"What is the purpose of git status, and why should it be used frequently?","kind":"long","points":2,"options":[],"manual":true,"required":true},{"id":"q6","prompt":"Why are meaningful commit messages important? Provide two examples.","kind":"long","points":2,"options":[],"manual":true,"required":true},{"id":"q7","prompt":"You create file1.txt and file2.txt, then execute git add file1.txt. Which file becomes staged, and which remains untracked? Explain.","kind":"scenario","points":2,"options":[],"manual":true,"required":true},{"id":"q8","prompt":"You create feature/test with git branch feature/test, and git branch displays an asterisk next to main. Which branch are you on, and how would you switch?","kind":"scenario","points":2,"options":[],"manual":true,"required":true},{"id":"q9","prompt":"You are currently on feature/skills and execute git merge main. Which branch receives the changes? Does it update main?","kind":"scenario","points":2,"options":[],"manual":true,"required":true},{"id":"q10","prompt":"You modified notes.txt, but git commit -m \"Update notes\" reports \"Changes not staged for commit.\" Explain the problem and provide the necessary commands.","kind":"scenario","points":2,"options":[],"manual":true,"required":true},{"id":"q11","prompt":"A new file seems to disappear when switching from a feature branch back to main. Explain why and how to access the file again.","kind":"scenario","points":2,"options":[],"manual":true,"required":true},{"id":"q12","prompt":"What is the difference between creating a branch and switching to a branch? Provide example commands.","kind":"scenario","points":2,"options":[],"manual":true,"required":true},{"id":"isolation","prompt":"Explain the branch isolation you observed when switching between main and feature/skills.","kind":"long","points":0,"options":[],"manual":true,"required":true},{"id":"merge","prompt":"Explain the direction and type of your Part 4 merge. Was a new merge commit created? Why?","kind":"long","points":0,"options":[],"manual":true,"required":true},{"id":"bonus","prompt":"Optional bonus reflection: What happened during the merge? How did it differ from Part 4? Why might Git create a merge commit, and what does the graph reveal?","kind":"long","points":0,"options":[],"manual":true,"required":false}]}'::jsonb from public.assignments a cross join lateral (select 1 as version union select a.version union select assignment_version from public.attempts where assignment_id=a.id) v where a.id='b6f4b6d0-5fe2-4e4d-b9a5-000000000001' on conflict(assessment_id,version) do nothing;
insert into private.assessment_keys(assessment_id,version,keys) select assessment_id,version,'{}' from public.assessment_versions where assessment_id='b6f4b6d0-5fe2-4e4d-b9a5-000000000001' on conflict do nothing;
