update public.assignments set published_version=version where id='b6f4b6d0-5fe2-4e4d-b9a5-000000000001';
-- Other manually-created legacy records remain untouched. Publish a validated definition before creating new attempts for them.

-- Compatibility RPC must obey the same timer and attempt policy; it cannot open an untimed exam.
create or replace function public.start_attempt(p_assignment uuid) returns public.attempts language plpgsql security definer set search_path='' as $$declare result jsonb;a public.attempts;begin result:=public.start_assessment(p_assignment);select * into a from public.attempts where id=(result->>'id')::uuid;return a;end $$;

create table public.question_bank(id uuid primary key default gen_random_uuid(),document jsonb not null,archived boolean not null default false,updated_at timestamptz not null default now());
alter table public.question_bank enable row level security;revoke all on public.question_bank from anon,authenticated;grant select on public.question_bank to authenticated;
create policy question_bank_instructor on public.question_bank for select to authenticated using((select public.is_instructor()));
create function public.save_bank_question(p_id uuid,p_document jsonb) returns uuid language plpgsql security definer set search_path='' as $$declare target uuid:=coalesce(p_id,gen_random_uuid());begin
 if auth.uid() is null or not public.is_instructor() then raise exception 'Instructor authorization required';end if;if octet_length(p_document::text)>30000 or length(trim(p_document->>'prompt')) not between 1 and 8000 then raise exception 'Invalid question';end if;
 insert into public.question_bank(id,document) values(target,p_document) on conflict(id) do update set document=excluded.document,updated_at=now(),archived=false;return target;end $$;
create function public.archive_bank_question(p_id uuid,p_archived boolean) returns void language plpgsql security definer set search_path='' as $$begin if auth.uid() is null or not public.is_instructor() then raise exception 'Instructor authorization required';end if;update public.question_bank set archived=p_archived where id=p_id;end $$;
revoke all on function public.save_bank_question(uuid,jsonb),public.archive_bank_question(uuid,boolean) from public,anon;grant execute on function public.save_bank_question(uuid,jsonb),public.archive_bank_question(uuid,boolean) to authenticated;


